213	export function Shell({
214	  nav,
215	  user,
216	  notifications,
217	  impersonation,
218	  tag,
219	  children,
220	}: {
221	  nav: NavSection[];
222	  user: { name: string; email: string; role: string; balanceCents: number };
223	  notifications: ShellNotification[];
224	  impersonation?: { adminName: string; targetEmail: string } | null;
225	  tag?: string;
226	  children: React.ReactNode;
227	}) {
228	  const pathname = usePathname();
229	  // Which portal is this Shell rendering? The admin ops layout is the only caller
230	  // that passes tag="ops"; the customer dashboard passes none. This drives which
231	  // floating widgets mount: the customer portal keeps the Feedback bubble (and the
232	  // live-chat bubble from the root layout), while the admin portal swaps them for
233	  // the staff-facing support + email attention indicators. (Role is NOT a reliable
234	  // signal here — an ADMIN visiting /dashboard is still on the customer portal.)
235	  const isAdminPortal = tag === "ops";
236	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
237	  // main so they fill the entire content area under the header with no gap.
238	  const fullBleed =
239	    pathname === "/dashboard/mail" || pathname === "/dashboard/calendar" || pathname === "/admin/inbox" || pathname === "/admin/board";
240	  const [notifOpen, setNotifOpen] = useState(false);
241	  const [sidebarOpen, setSidebarOpen] = useState(false);
242	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
243	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
244	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
245	  const [collapsed, setCollapsed] = useState(false);
246	  const [, startTransition] = useTransition();
247	
248	  useEffect(() => {
249	    try {
250	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
251	    } catch {}
252	  }, []);
253	  function toggleCollapsed() {
254	    setCollapsed((c) => {
255	      const next = !c;
256	      try {
257	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
258	      } catch {}
259	      return next;
260	    });
261	  }
262	
263	  /**
264	   * Publish the rail's current width so `position: fixed` chrome outside this
265	   * subtree can sit beside it instead of guessing.
266	   *
267	   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
268	   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
269	   * whenever a customer collapsed the sidebar. A CSS variable on the document
270	   * element reaches the dock regardless of where it is mounted.
271	   */
272	  useEffect(() => {
273	    document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
274	  }, [collapsed]);
275	
276	  /**
277	   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
278	   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
279	   * page sidebar and must never be hidden or inerted.
280	   *
281	   * Starts `true` (desktop) so the server render and the first client render
282	   * agree, and so a JS-less or pre-hydration page never has its navigation
283	   * inerted. The listener corrects it a tick later.
284	   */
285	  const [isDesktopRail, setIsDesktopRail] = useState(true);
286	  useEffect(() => {
287	    const mq = window.matchMedia("(min-width: 1024px)");
288	    const sync = () => setIsDesktopRail(mq.matches);
289	    sync();
290	    mq.addEventListener("change", sync);
291	    return () => mq.removeEventListener("change", sync);
292	  }, []);
293	  /**
294	   * Closed, off-canvas and out of reach. The rehearsal found the closed drawer
295	   * still `visibility: visible` with no `aria-hidden` and **25 focusable
296	   * descendants in the tab order** — so a keyboard user on a phone tabbed
297	   * through the entire hidden navigation before reaching the page.
298	   */
299	  const drawerHidden = !isDesktopRail && !sidebarOpen;
300	
301	  // Escape closes the drawer. It did nothing at all before: the drawer had no
302	  // close button either (the only in-drawer button is the collapse toggle, which
303	  // is `lg:flex`), so a backdrop tap was the single way out.
304	  useEffect(() => {
305	    if (!sidebarOpen) return;
306	    const onKey = (e: KeyboardEvent) => {
307	      if (e.key === "Escape") setSidebarOpen(false);
308	    };
309	    window.addEventListener("keydown", onKey);
310	    return () => window.removeEventListener("keydown", onKey);
311	  }, [sidebarOpen]);
312	
313	  // Navigating from a drawer link must close the drawer — otherwise the new page
314	  // renders behind a panel the customer has to dismiss by hand.
315	  useEffect(() => {
316	    setSidebarOpen(false);
317	  }, [pathname]);
318	
319	  // Opening the bell marks everything read server-side, but `notifications` is a
320	  // prop rendered from the initial server load, so without this the blue count
321	  // and the bold titles would stay lit for the rest of the session even though
322	  // the server now considers them read — a "you have unread mail" badge that
323	  // won't clear. Track the open-and-marked edge locally and reconcile the view
324	  // to it. Once marked, unread is 0 and nothing renders as unread.
325	  const [notifMarked, setNotifMarked] = useState(false);
326	  // The optimistic clear only covers the window between opening the bell and the
327	  // server revalidating. Once a fresh `notifications` prop arrives (e.g. a new
328	  // notification, or the read state confirmed), drop the optimism so a genuinely
329	  // new unread item still lights the badge.
330	  useEffect(() => {
331	    setNotifMarked(false);
332	  }, [notifications]);
333	  const unread = notifMarked ? 0 : notifications.filter((n) => !n.readAt).length;
334	
335	  // Live unread-INBOX count for the "Inbox" nav badge. Polled client-side because
336	  // IMAP is far too slow to run on every server-side layout render. Only polls when
337	  // the portal actually has a Mail entry; fails soft to no badge.
338	  const hasMailNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/mail"));
339	  const [mailUnread, setMailUnread] = useState(0);
340	  useEffect(() => {
341	    if (!hasMailNav) return;
342	    let alive = true;
343	    const load = () =>
344	      fetch("/api/mail/unread")
345	        .then((r) => (r.ok ? r.json() : { unread: 0 }))
346	        .then((d) => alive && setMailUnread(Number(d?.unread) || 0))
347	        .catch(() => {});
348	    load();
349	    const id = setInterval(load, 60_000);
350	    return () => {
351	      alive = false;
352	      clearInterval(id);
353	    };
354	  }, [hasMailNav]);
355	
356	  // Live Matrix status for the "Matrix" nav tag. Polls the user's own console
357	  // builds: shows "running" while a build is in flight, and "update" when one
358	  // has reached a state worth a look (finished, or a plan awaiting approval)
359	  // that the customer hasn't seen since they last opened the workspace. Only
360	  // polls when the portal has a Matrix entry; fails soft to no tag.
361	  const hasMatrixNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/build"));
362	  const [matrixStatus, setMatrixStatus] = useState<{
363	    running: number;
364	    needsAttention: number;
365	    lastEventAt: string | null;
366	  }>({ running: 0, needsAttention: 0, lastEventAt: null });
367	  // Timestamp (ms) the customer last "saw" Matrix. Seeded to now on first ever
368	  // load so pre-existing finished builds don't light a stale "update" tag —
369	  // only events from here forward count. Bumped whenever they open the workspace.
370	  const [matrixSeenAt, setMatrixSeenAt] = useState<number>(0);
371	  useEffect(() => {
372	    try {
373	      const v = localStorage.getItem("nxeon.matrix.seenAt");
374	      if (v) {
375	        setMatrixSeenAt(Number(v) || 0);
376	      } else {
377	        const now = Date.now();
378	        setMatrixSeenAt(now);
379	        localStorage.setItem("nxeon.matrix.seenAt", String(now));
380	      }
381	    } catch {
382	      setMatrixSeenAt(Date.now());
383	    }
384	  }, []);
385	  useEffect(() => {
386	    if (!hasMatrixNav) return;
387	    let alive = true;
388	    const load = () =>
389	      fetch("/api/claude/console-status")
390	        .then((r) => (r.ok ? r.json() : null))
391	        .then((d) => {
392	          if (alive && d) {
393	            setMatrixStatus({
394	              running: Number(d.running) || 0,
395	              needsAttention: Number(d.needsAttention) || 0,
396	              lastEventAt: d.lastEventAt ?? null,
397	            });
398	          }
399	        })
400	        .catch(() => {});
401	    load();
402	    const id = setInterval(load, 20_000);
403	    return () => {
404	      alive = false;
405	      clearInterval(id);
406	    };
407	  }, [hasMatrixNav]);
408	  // Opening the workspace marks everything seen (clears the "update" tag). Also
409	  // re-marks if a fresh event lands while they're already on the page.
410	  useEffect(() => {
411	    if (pathname !== "/dashboard/build") return;
412	    const now = Date.now();
413	    setMatrixSeenAt(now);
414	    try {
415	      localStorage.setItem("nxeon.matrix.seenAt", String(now));
416	    } catch {}
417	  }, [pathname, matrixStatus.lastEventAt]);
418	  const matrixTag: "running" | "update" | null =
419	    matrixStatus.running > 0
420	      ? "running"
421	      : matrixStatus.lastEventAt != null && Date.parse(matrixStatus.lastEventAt) > matrixSeenAt
422	        ? "update"
423	        : null;
424	
425	  // Escape closes the notifications dropdown too (it only closed the drawer
426	  // before), matching the palette and drawer. A click anywhere else dismisses it
427	  // via the click-away layer rendered below.
428	  useEffect(() => {
429	    if (!notifOpen) return;
430	    const onKey = (e: KeyboardEvent) => {
431	      if (e.key === "Escape") setNotifOpen(false);
432	    };
433	    window.addEventListener("keydown", onKey);
434	    return () => window.removeEventListener("keydown", onKey);
435	  }, [notifOpen]);
436	
437	  // Flatten for the command palette: every sidebar entry plus every secondary
438	  // destination hidden behind it, so ⌘K still reaches all ~41 admin routes even
439	  // though only 14 of them have a sidebar row. The child sharing the entry's own
440	  // href is skipped so the landing page isn't listed twice. Flat items (customer
441	  // portal) pass through unchanged.
442	  const flatNav = nav.flatMap((s) =>
443	    s.items.flatMap((i) => [
444	      { label: i.label, href: i.href, section: s.label },
445	      ...(i.children ?? [])
446	        .filter((c) => c.href !== i.href)
447	        .map((c) => ({ label: c.label, href: c.href, section: s.label })),
448	    ])
449	  );
450	
451	  return (
452	    // The terminal dock lives at the shell level so a shell session survives
453	    // in-portal navigation: App Router keeps Shell mounted across page changes,
454	    // so the dock (and its live sockets) is never unmounted. The provider is
455	    // inert until a page calls useTerminalDock().openSession(...).
456	    <TerminalDockProvider>
457	    {/* The compose provider lives at the shell level for the same reason as the
458	        terminal dock: App Router keeps Shell mounted across in-portal navigation,
459	        so an open (or minimized) mail composer — and its in-progress draft —
460	        survives moving between dashboard pages. It renders the composer through a
461	        portal to <body> and is inert until a mail page calls useCompose().open(). */}
462	    <ComposeProvider>
463	    {/* The Matrix workspace lives at the shell level for the same reason as the
464	        terminal dock and compose provider: App Router keeps Shell mounted across
465	        in-portal navigation, so open build consoles and their live server
466	        terminals survive moving between pages. It is lazy (nothing until the
467	        customer first opens Matrix) and inert on every non-customer route. */}
468	    <MatrixProvider>
469	    <div className="flex min-h-screen">
470	      <CommandPalette nav={flatNav} />
471	      {/* Customer portal: the Feedback bubble (+ the live-chat bubble mounted by
472	          the root layout). Admin ops portal: staff-facing support + email
473	          attention indicators instead (the customer widgets are suppressed on
474	          /admin). */}
475	      {isAdminPortal ? <AdminIndicators /> : <FeedbackWidget />}
476	      <VisitTracker kind="portal" />
477	
478	      {/* Sidebar */}
